-- -----------------------------------
-- Table structure for `newnetwork_report_new_test`
-- -----------------------------------

DROP TABLE IF EXISTS `newnetwork_report_new_test`;
CREATE TABLE `newnetwork_report_new_test` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `SN` int(11) NOT NULL,
  `month_date` date NOT NULL,
  `month` int(11) NOT NULL,
  `year` int(11) NOT NULL,
  `uptime` float NOT NULL,
  `downtime` float NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_update` tinyint(4) NOT NULL DEFAULT '0',
  `today_tot_hit` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `SN` (`SN`),
  KEY `SN_2` (`SN`),
  KEY `SN_3` (`SN`),
  KEY `SN_4` (`SN`),
  KEY `SN_5` (`SN`),
  KEY `SN_6` (`SN`),
  KEY `SN_7` (`SN`),
  KEY `SN_8` (`SN`),
  KEY `SN_9` (`SN`),
  KEY `SN_10` (`SN`)
) ENGINE=MyISAM AUTO_INCREMENT=2306 DEFAULT CHARSET=latin1;

